public record Money(long minor, String currency) {
    private static final Pattern ISO = Pattern.compile("[A-Z]{3}");

    public Money {
        Objects.requireNonNull(currency, "currency");
        currency = currency.trim().toUpperCase(Locale.ROOT);   // normalize in place
        if (!ISO.matcher(currency).matches()) throw new IllegalArgumentException("bad currency: " + currency);
        if (minor < 0) throw new IllegalArgumentException("negative amount: " + minor);
    }

    public Money plus(Money other) {
        if (!currency.equals(other.currency)) throw new IllegalArgumentException("currency mismatch");
        return new Money(Math.addExact(minor, other.minor), currency);
    }
}

kotlin.src:
data class Money(val minor: Long, val currency: String) {
    init {
        require(ISO.matches(currency)) { "bad currency: $currency" }   // can reject, can't normalize
        require(minor >= 0) { "negative amount: $minor" }
    }

    operator fun plus(other: Money): Money {
        require(currency == other.currency) { "currency mismatch" }
        return Money(Math.addExact(minor, other.minor), currency)
    }

    companion object {
        private val ISO = Regex("[A-Z]{3}")
        fun of(minor: Long, currency: String) = Money(minor, currency.trim().uppercase())
    }
}

